import * as THREE from 'three';

/* DRESSES_START */
// Generated by data/make_dresses.js, do not edit by hand.
const DRESSES = [
  { name: "Linen Floral Midi", length: 0.05, formality: -0.25, colour: -0.68, dataUri: "data:image/svg+xml;base64," },
  { name: "Ivory Lace Maxi", length: 0.9, formality: 0.85, colour: -0.86, dataUri: "data:image/svg+xml;base64," },
  { name: "Sage Chiffon Wrap Dress", length: 0.25, formality: 0.3, colour: -0.42, dataUri: "data:image/svg+xml;base64," },
  { name: "Black Wool Sheath", length: -0.15, formality: 0.55, colour: 0.79, dataUri: "data:image/svg+xml;base64," },
  { name: "Striped Beach Cover-up", length: -0.6, formality: -0.95, colour: -0.87, dataUri: "data:image/svg+xml;base64," },
  { name: "Lavender-Print Sundress", length: -0.2, formality: -0.55, colour: -0.49, dataUri: "data:image/svg+xml;base64," },
  { name: "Sequin Cocktail Dress", length: -0.55, formality: 0.75, colour: -0.20, dataUri: "data:image/svg+xml;base64," },
  { name: "Pale Blue Cotton Midi", length: 0.15, formality: -0.35, colour: -0.67, dataUri: "data:image/svg+xml;base64," },
  { name: "Velvet Midi", length: 0.3, formality: 0.45, colour: 0.58, dataUri: "data:image/svg+xml;base64," },
  { name: "Blush Silk Slip Midi", length: 0.35, formality: 0.2, colour: -0.66, dataUri: "data:image/svg+xml;base64," },
  { name: "Terracotta Poplin Maxi", length: 0.75, formality: -0.05, colour: -0.02, dataUri: "data:image/svg+xml;base64," },
  { name: "Denim Mini", length: -0.9, formality: -0.75, colour: 0.23, dataUri: "data:image/svg+xml;base64," },
  { name: "Red Satin Gown", length: 1, formality: 1, colour: 0.28, dataUri: "data:image/svg+xml;base64," },
  { name: "Navy Shirt Dress", length: -0.05, formality: -0.1, colour: 0.57, dataUri: "data:image/svg+xml;base64," },
  { name: "White Tennis Dress", length: -0.85, formality: -0.6, colour: -0.94, dataUri: "data:image/svg+xml;base64," },
  { name: "Charcoal Jersey Maxi", length: 0.85, formality: -0.45, colour: 0.50, dataUri: "data:image/svg+xml;base64," }
];
/* DRESSES_END */

const COLS = 4;
const ROWS = 4;
const SPACING_X = 2.05;
const SPACING_Y = 2.3;
const CARD_H = 2.0;
const CARD_W = CARD_H * 0.75;
const AXIS_SCALE = 5.0;
// Formality runs vertically, where the title and footer leave less room.
const Y_SCALE = 4.0;
const SHRINK_TO = 0.5;
const LERP = 0.08;
const MAX_STAGE = 4;
const CAM_BASE = 21.6;
const CAM_WIDE = 30.0;
const CAM_ORBIT_Y = 0.55;
const CAM_ORBIT_X = 0.28;
const CAM_SPIN_PERIOD = 20;

// --- hyperspace cloud (final beat) ---
const CLOUD_N = 6000;
const DIM = 8;
const CLUSTERS = 6;
const HD_SPREAD = 2.4;   // cluster-centre spread in D-space
const HD_SIGMA = 0.7;    // within-cluster gaussian sigma
const CLOUD_GAIN = 1.7;  // D-space → world-space scale
const TUMBLE_RATE = 0.5; // base angular speed of the projection basis
const POINT_SIZE = 240;  // gl_PointSize = POINT_SIZE * pixelRatio / dist
const CLOUD_PALETTE = [0x49bcff, 0x175fff, 0x00dcc6, 0xc84cff, 0x7f47ff, 0x9ed8ff];

// Deterministic so the cloud reads the same on every run (mulberry32).
function makeRng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gaussian(rng) {
  let u = 0;
  while (u === 0) u = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rng());
}

function hexRGB(hex) {
  return [((hex >> 16) & 255) / 255, ((hex >> 8) & 255) / 255, (hex & 255) / 255];
}

function vecNormalize(v) {
  let s = 0;
  for (let i = 0; i < v.length; i++) s += v[i] * v[i];
  s = Math.sqrt(s) || 1;
  for (let i = 0; i < v.length; i++) v[i] /= s;
}

function vecSubProj(v, onto) {
  let dot = 0;
  for (let i = 0; i < v.length; i++) dot += v[i] * onto[i];
  for (let i = 0; i < v.length; i++) v[i] -= dot * onto[i];
}

export default function init({ canvas }) {
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setClearColor(0xffffff, 1);
  const w = canvas.clientWidth || canvas.width;
  const h = canvas.clientHeight || canvas.height;
  renderer.setSize(w, h, false);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(35, w / h, 0.1, 200);
  camera.position.set(0, 0, CAM_BASE);
  camera.lookAt(0, 0, 0);

  const loader = new THREE.TextureLoader();
  const cardGeo = new THREE.PlaneGeometry(CARD_W, CARD_H);

  const cards = [];
  const cardMats = [];
  const textures = [];
  const layouts = [[], [], [], []];

  const xOffset = -((COLS - 1) * SPACING_X) / 2;
  const yOffset = ((ROWS - 1) * SPACING_Y) / 2 - 0.6;

  DRESSES.forEach((dress, i) => {
    const col = i % COLS;
    const row = Math.floor(i / COLS);
    const gx = xOffset + col * SPACING_X;
    const gy = yOffset - row * SPACING_Y;
    const x = dress.length * AXIS_SCALE;
    const y = dress.formality * Y_SCALE;
    const z = dress.colour * AXIS_SCALE;
    layouts[0].push(new THREE.Vector3(gx, gy, 0));
    layouts[1].push(new THREE.Vector3(x, 0, 0));
    layouts[2].push(new THREE.Vector3(x, y, 0));
    layouts[3].push(new THREE.Vector3(x, y, z));

    const tex = loader.load(dress.dataUri);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    tex.generateMipmaps = false;
    const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, alphaTest: 0.01 });
    const card = new THREE.Mesh(cardGeo, mat);
    card.position.copy(layouts[0][i]);
    scene.add(card);

    cards.push(card);
    cardMats.push(mat);
    textures.push(tex);
  });

  const axisLen = AXIS_SCALE * 1.2;
  const xAxisGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-axisLen, 0, 0),
    new THREE.Vector3(axisLen, 0, 0),
  ]);
  const yAxisGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, -Y_SCALE * 1.15, 0),
    new THREE.Vector3(0, Y_SCALE * 1.15, 0),
  ]);
  const zAxisGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, -axisLen),
    new THREE.Vector3(0, 0, axisLen),
  ]);
  const xAxisMat = new THREE.LineBasicMaterial({ color: 0x7d8a9e, transparent: true, opacity: 0 });
  const yAxisMat = new THREE.LineBasicMaterial({ color: 0x7d8a9e, transparent: true, opacity: 0 });
  const zAxisMat = new THREE.LineBasicMaterial({ color: 0x7d8a9e, transparent: true, opacity: 0 });
  scene.add(new THREE.Line(xAxisGeo, xAxisMat));
  scene.add(new THREE.Line(yAxisGeo, yAxisMat));
  scene.add(new THREE.Line(zAxisGeo, zAxisMat));

  // Pole labels, one pair per axis, fading in with their axis line.
  function makeLabel(text, pos) {
    const c = document.createElement('canvas');
    c.width = 512;
    c.height = 128;
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    const draw = () => {
      const ctx = c.getContext('2d');
      ctx.clearRect(0, 0, c.width, c.height);
      ctx.font = '600 64px Inter, system-ui, sans-serif';
      ctx.fillStyle = '#061982';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(text, c.width / 2, c.height / 2);
      tex.needsUpdate = true;
    };
    draw();
    document.fonts?.ready.then(draw);
    const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, opacity: 0, depthWrite: false });
    const sprite = new THREE.Sprite(mat);
    sprite.scale.set(2.8, 0.7, 1);
    sprite.position.copy(pos);
    scene.add(sprite);
    textures.push(tex);
    return mat;
  }
  const labelGap = axisLen + 1.3;
  const xLabels = [
    makeLabel('short', new THREE.Vector3(-labelGap, 0, 0)),
    makeLabel('long', new THREE.Vector3(labelGap, 0, 0)),
  ];
  const yLabels = [
    makeLabel('casual', new THREE.Vector3(0, -Y_SCALE * 1.15 - 0.55, 0)),
    makeLabel('formal', new THREE.Vector3(0, Y_SCALE * 1.15 + 0.55, 0)),
  ];
  const zLabels = [
    makeLabel('dark', new THREE.Vector3(0, 0, labelGap)),
    makeLabel('light', new THREE.Vector3(0, 0, -labelGap)),
  ];

  // --- hyperspace cloud ---
  const rng = makeRng(0x5eedface);
  const centers = [];
  for (let c = 0; c < CLUSTERS; c++) {
    const ctr = new Float32Array(DIM);
    for (let d = 0; d < DIM; d++) ctr[d] = (rng() * 2 - 1) * HD_SPREAD;
    centers.push(ctr);
  }

  const hd = new Float32Array(CLOUD_N * DIM); // point coords in D-space
  const cloudPos = new Float32Array(CLOUD_N * 3); // projected, refilled each frame
  const cloudCol = new Float32Array(CLOUD_N * 3);
  const cloudSeed = new Float32Array(CLOUD_N);
  for (let i = 0; i < CLOUD_N; i++) {
    const c = i % CLUSTERS;
    const ctr = centers[c];
    for (let d = 0; d < DIM; d++) hd[i * DIM + d] = ctr[d] + gaussian(rng) * HD_SIGMA;
    const rgb = hexRGB(CLOUD_PALETTE[c]);
    cloudCol[i * 3] = rgb[0];
    cloudCol[i * 3 + 1] = rgb[1];
    cloudCol[i * 3 + 2] = rgb[2];
    cloudSeed[i] = rng();
  }

  const cloudGeo = new THREE.BufferGeometry();
  cloudGeo.setAttribute('position', new THREE.BufferAttribute(cloudPos, 3));
  cloudGeo.setAttribute('aColor', new THREE.BufferAttribute(cloudCol, 3));
  cloudGeo.setAttribute('aSeed', new THREE.BufferAttribute(cloudSeed, 1));

  const cloudMat = new THREE.ShaderMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.NormalBlending,
    uniforms: {
      uOpacity: { value: 0 },
      uSize: { value: POINT_SIZE },
      uTime: { value: 0 },
      uPixelRatio: { value: renderer.getPixelRatio() },
    },
    vertexShader: `
      attribute vec3 aColor;
      attribute float aSeed;
      uniform float uSize;
      uniform float uPixelRatio;
      varying vec3 vColor;
      varying float vSeed;
      void main() {
        vColor = aColor;
        vSeed = aSeed;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        gl_PointSize = uSize * uPixelRatio / max(-mv.z, 0.1);
        gl_Position = projectionMatrix * mv;
      }
    `,
    fragmentShader: `
      uniform float uOpacity;
      uniform float uTime;
      varying vec3 vColor;
      varying float vSeed;
      void main() {
        float r = length(gl_PointCoord - 0.5);
        if (r > 0.5) discard;
        float glow = pow(smoothstep(0.5, 0.0, r), 1.6);
        float tw = 0.7 + 0.3 * sin(uTime * 1.5 + vSeed * 6.2831853);
        gl_FragColor = vec4(vColor, glow * uOpacity * tw);
      }
    `,
  });
  const cloudPoints = new THREE.Points(cloudGeo, cloudMat);
  cloudPoints.frustumCulled = false;
  scene.add(cloudPoints);

  // Orthonormal projection basis in D-space; rotating it tumbles the cloud
  // through its hidden dimensions.
  const basis = [new Float32Array(DIM), new Float32Array(DIM), new Float32Array(DIM)];
  basis[0][0] = 1;
  basis[1][1] = 1;
  basis[2][2] = 1;
  const TUMBLE_PLANES = [[0, 3], [1, 5], [2, 6], [4, 7]];
  let tumblePhase = 0;
  let tumbleFrames = 0;

  function tumble(dt, rate) {
    tumblePhase += dt;
    for (let k = 0; k < TUMBLE_PLANES.length; k++) {
      const p = TUMBLE_PLANES[k][0];
      const q = TUMBLE_PLANES[k][1];
      const ang = rate * dt * (0.6 + 0.4 * Math.sin(tumblePhase * 0.2 + k));
      const cs = Math.cos(ang);
      const sn = Math.sin(ang);
      for (let b = 0; b < 3; b++) {
        const vec = basis[b];
        const a = vec[p];
        const bb = vec[q];
        vec[p] = a * cs - bb * sn;
        vec[q] = a * sn + bb * cs;
      }
    }
    if (++tumbleFrames % 90 === 0) {
      vecNormalize(basis[0]);
      vecSubProj(basis[1], basis[0]);
      vecNormalize(basis[1]);
      vecSubProj(basis[2], basis[0]);
      vecSubProj(basis[2], basis[1]);
      vecNormalize(basis[2]);
    }
  }

  function projectCloud(gain) {
    const u = basis[0];
    const v = basis[1];
    const wv = basis[2];
    for (let i = 0; i < CLOUD_N; i++) {
      const o = i * DIM;
      let x = 0;
      let y = 0;
      let z = 0;
      for (let d = 0; d < DIM; d++) {
        const val = hd[o + d];
        x += val * u[d];
        y += val * v[d];
        z += val * wv[d];
      }
      const p = i * 3;
      cloudPos[p] = x * gain;
      cloudPos[p + 1] = y * gain;
      cloudPos[p + 2] = z * gain;
    }
    cloudGeo.attributes.position.needsUpdate = true;
  }

  let cloudTime = 0;

  let stage = 0;
  let targetT = 0;
  let currentT = 0;

  const LAYOUT_MAX = layouts.length - 1;
  function applyLayout(t) {
    const idx = Math.floor(t);
    const frac = t - idx;
    const fromArr = layouts[Math.min(idx, LAYOUT_MAX)];
    const toArr = layouts[Math.min(idx + 1, LAYOUT_MAX)];
    const s = 1 + (SHRINK_TO - 1) * Math.min(t, 1);
    for (let i = 0; i < cards.length; i++) {
      cards[i].position.lerpVectors(fromArr[i], toArr[i], frac);
      cards[i].scale.setScalar(s);
    }

    // Final beat (t in [3,4]): dresses and axes give way to the cloud.
    const w = THREE.MathUtils.clamp(t - 3, 0, 1);
    const cardFade = 1 - w;
    // Once the cloud is showing, stop the (now-transparent) cards writing
    // depth, or they punch holes in the points behind.
    const writeDepth = w === 0;
    for (let i = 0; i < cardMats.length; i++) {
      cardMats[i].opacity = cardFade;
      cardMats[i].depthWrite = writeDepth;
    }
    const xa = THREE.MathUtils.clamp(t, 0, 1) * cardFade;
    const ya = THREE.MathUtils.clamp(t - 1, 0, 1) * cardFade;
    const za = THREE.MathUtils.clamp(t - 2, 0, 1) * cardFade;
    xAxisMat.opacity = 0.45 * xa;
    yAxisMat.opacity = 0.45 * ya;
    zAxisMat.opacity = 0.45 * za;
    for (const m of xLabels) m.opacity = 0.85 * xa;
    for (const m of yLabels) m.opacity = 0.85 * ya;
    for (const m of zLabels) m.opacity = 0.85 * za;
    cloudMat.uniforms.uOpacity.value = w;
  }

  let spinAngle = 0;
  const SPIN_RATE = (Math.PI * 2) / CAM_SPIN_PERIOD;
  function applyCamera(t) {
    const t3 = THREE.MathUtils.clamp(t - 2, 0, 1);
    const w = THREE.MathUtils.clamp(t - 3, 0, 1);
    const angleY = t3 * CAM_ORBIT_Y + spinAngle;
    const angleX = t3 * CAM_ORBIT_X;
    const r = CAM_BASE + (CAM_WIDE - CAM_BASE) * w;
    camera.position.x = Math.sin(angleY) * r * Math.cos(angleX);
    camera.position.z = Math.cos(angleY) * r * Math.cos(angleX);
    camera.position.y = Math.sin(angleX) * r;
    camera.lookAt(0, 0, 0);
  }

  function orientCards() {
    for (const card of cards) card.lookAt(camera.position);
  }

  let raf = 0;
  let lastTime = 0;
  function loop(now) {
    const dt = lastTime ? (now - lastTime) / 1000 : 0;
    lastTime = now;
    currentT += (targetT - currentT) * LERP;
    if (targetT >= 3) {
      const spinWeight = THREE.MathUtils.clamp(currentT - 2, 0, 1);
      spinAngle += dt * SPIN_RATE * spinWeight;
      if (spinAngle > Math.PI) spinAngle -= 2 * Math.PI;
      if (spinAngle < -Math.PI) spinAngle += 2 * Math.PI;
    } else {
      spinAngle += (0 - spinAngle) * LERP;
    }
    applyLayout(currentT);
    applyCamera(currentT);
    orientCards();
    const w = THREE.MathUtils.clamp(currentT - 3, 0, 1);
    if (w > 0.001) {
      cloudTime += dt;
      cloudMat.uniforms.uTime.value = cloudTime;
      tumble(dt, TUMBLE_RATE * w);
      projectCloud(CLOUD_GAIN * (0.6 + 0.4 * w));
    }
    renderer.render(scene, camera);
    raf = requestAnimationFrame(loop);
  }
  raf = requestAnimationFrame(loop);

  function onResize() {
    const cw = canvas.clientWidth || canvas.width;
    const ch = canvas.clientHeight || canvas.height;
    camera.aspect = cw / ch;
    camera.updateProjectionMatrix();
    renderer.setSize(cw, ch, false);
    cloudMat.uniforms.uPixelRatio.value = renderer.getPixelRatio();
  }
  window.addEventListener('resize', onResize);

  return {
    advance() {
      if (stage < MAX_STAGE) {
        stage++;
        targetT = stage;
        return true;
      }
      return false;
    },
    retreat() {
      if (stage > 0) {
        stage--;
        targetT = stage;
        return true;
      }
      return false;
    },
    dispose() {
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', onResize);
      cardGeo.dispose();
      cloudGeo.dispose();
      cloudMat.dispose();
      xAxisGeo.dispose();
      yAxisGeo.dispose();
      zAxisGeo.dispose();
      xAxisMat.dispose();
      yAxisMat.dispose();
      zAxisMat.dispose();
      for (const m of [...cardMats, ...xLabels, ...yLabels, ...zLabels]) m.dispose();
      for (const t of textures) t.dispose();
      renderer.dispose();
    },
  };
}
